1	package testutil
2	
3	import (
4		"fmt"
5		"go/ast"
6		"go/parser"
7		"go/token"
8		"io/fs"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"testing"
15	)
16	
17	// DEVDESK-199: tests build key presses and pick a colour profile through the
18	// helpers in this package and internal/testutil/colorprofile, never by hand.
19	// A hand-built tea.KeyMsg{Type: tea.KeyRunes, Runes: ...} drifts from what the
20	// terminal really sends, and lipgloss.SetColorProfile / termenv leak a global
21	// across tests. This guard reads every *_test.go the way internal/ui/keymap's
22	// scans do, and names file:line for each offence.
23	//
24	// Using tea.KeyMsg as a TYPE (assertion, parameter, return) stays allowed.
25	
26	const (
27		bubbleteaPath = "github.com/charmbracelet/bubbletea"
28		termenvPath   = "github.com/muesli/termenv"
29	)
30	
31	// fieldSelectorExceptions lists "<slash path suffix>:<selector>" pairs allowed
32	// to use .Runes / .Alt / .Paste. Empty on purpose: every entry needs a reason
33	// written next to it.
34	var fieldSelectorExceptions = map[string]string{}
35	
36	var bannedFields = map[string]bool{"Runes": true, "Alt": true, "Paste": true}
37	
38	// skippedDirs are module-relative slash paths the scan does not enter.
39	var skippedDirs = []string{"internal/ui/testutil", "internal/testutil/colorprofile"}
40	
41	// guardSource returns one message per offence in src ("name:line: reason").
42	func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
43		file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
44		if err != nil {
45			return nil, err
46		}
47		var teaNames []string
48		var out []string
49		report := func(pos token.Pos, format string, args ...any) {
50			out = append(out, fmt.Sprintf("%s: %s", fset.Position(pos), fmt.Sprintf(format, args...)))
51		}
52		for _, imp := range file.Imports {
53			p, _ := strconv.Unquote(imp.Path.Value)
54			switch p {
55			case bubbleteaPath:
56				n := "tea"
57				if imp.Name != nil {
58					n = imp.Name.Name
59				}
60				if n != "_" && n != "." {
61					teaNames = append(teaNames, n)
62				}
63			case termenvPath:
64				report(imp.Pos(), "imports %s; use internal/testutil/colorprofile", termenvPath)
65			}
66		}
67		isTea := func(e ast.Expr) (string, bool) {
68			id, ok := e.(*ast.Ident)
69			if !ok {
70				return "", false
71			}
72			for _, n := range teaNames {
73				if id.Name == n {
74					return n, true
75				}
76			}
77			return "", false
78		}
79		slash := filepath.ToSlash(name)
80		ast.Inspect(file, func(n ast.Node) bool {
81			switch x := n.(type) {
82			case *ast.CompositeLit:
83				if sel, ok := x.Type.(*ast.SelectorExpr); ok {
84					if pkg, ok := isTea(sel.X); ok && (sel.Sel.Name == "KeyMsg" || sel.Sel.Name == "Key") {
85						report(x.Pos(), "composite literal %s.%s; use testutil.Key/Keys/Type", pkg, sel.Sel.Name)
86					}
87				}
88			case *ast.SelectorExpr:
89				if pkg, ok := isTea(x.X); ok {
90					if strings.HasPrefix(x.Sel.Name, "Key") && x.Sel.Name != "KeyMsg" {
91						report(x.Pos(), "%s.%s; use testutil.Key/Keys/Type", pkg, x.Sel.Name)
92					}
93				} else if id, ok := x.X.(*ast.Ident); ok && id.Name == "testutil" {
94					// testutil.Paste is the sanctioned helper, a package-qualified
95					// call and not a field of a key message: not an offence.
96				} else if bannedFields[x.Sel.Name] {
97					allowed := false
98					for k := range fieldSelectorExceptions {
99						if i := strings.LastIndex(k, ":"); i > 0 && strings.HasSuffix(slash, k[:i]) && k[i+1:] == x.Sel.Name {
100							allowed = true
101						}
102					}
103					if !allowed {
104						report(x.Sel.Pos(), "selector .%s on a key message; use the testutil helpers", x.Sel.Name)
105					}
106				}
107				if id, ok := x.X.(*ast.Ident); ok && id.Name == "lipgloss" && x.Sel.Name == "SetColorProfile" {
108					report(x.Pos(), "lipgloss.SetColorProfile; use internal/testutil/colorprofile")
109				}
110			}
111			return true
112		})
113		return out, nil
114	}
115	
116	func moduleRoot(t *testing.T) string {
117		t.Helper()
118		dir, err := os.Getwd()
119		if err != nil {
120			t.Fatal(err)
121		}
122		for {
123			if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
124				return dir
125			}
126			parent := filepath.Dir(dir)
127			if parent == dir {
128				t.Fatal("go.mod not found above the working directory")
129			}
130			dir = parent
131		}
132	}
133	
134	func TestGuardNoHandBuiltKeysOrColorProfile(t *testing.T) {
135		root := moduleRoot(t)
136		fset := token.NewFileSet()
137		var violations []string
138		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
139			if err != nil {
140				return err
141			}
142			rel, _ := filepath.Rel(root, path)
143			rel = filepath.ToSlash(rel)
144			if d.IsDir() {
145				if rel != "." && strings.HasPrefix(d.Name(), ".") {
146					return filepath.SkipDir
147				}
148				for _, s := range skippedDirs {
149					if rel == s {
150						return filepath.SkipDir
151					}
152				}
153				return nil
154			}
155			if !strings.HasSuffix(path, "_test.go") {
156				return nil
157			}
158			v, err := guardSource(fset, rel, mustRead(t, path))
159			if err != nil {
160				t.Errorf("%s: %v", rel, err)
161				return nil
162			}
163			violations = append(violations, v...)
164			return nil
165		})
166		if err != nil {
167			t.Fatal(err)
168		}
169		sort.Strings(violations)
170		for _, v := range violations {
171			t.Errorf("%s", v)
172		}
173	}
174	
175	func mustRead(t *testing.T, path string) []byte {
176		t.Helper()
177		b, err := os.ReadFile(path)
178		if err != nil {
179			t.Fatal(err)
180		}
181		return b
182	}
183	
184	func TestGuardDetectorSelfTest(t *testing.T) {
185		const bad = `package x
186	
187	import (
188		tea "github.com/charmbracelet/bubbletea"
189		bt "github.com/charmbracelet/bubbletea"
190		"github.com/charmbracelet/lipgloss"
191		"github.com/muesli/termenv"
