195		_ = tea.KeyMsg{Type: tea.KeyEnter}
196		_ = bt.Key{}
197		_ = bt.KeyCtrlC
198		k := m.(tea.KeyMsg)
199		_ = k.Runes
200		_ = k.Alt
201		_ = k.Paste
202		lipgloss.SetColorProfile(termenv.Ascii)
203	}
204	`
205		const good = `package x
206	
207	import (
208		tea "github.com/charmbracelet/bubbletea"
209		"github.com/charmbracelet/lipgloss"
210		"x/testutil"
211	)
212	
213	type other struct{ KeyEnter int }
214	
215	func f(m tea.Msg, o other) tea.KeyMsg {
216		k, _ := m.(tea.KeyMsg)
217		_ = o.KeyEnter
218		_ = testutil.Paste("x")
219		_ = lipgloss.NewStyle()
220		return k
221	}
222	
223	`
224		got, err := guardSource(token.NewFileSet(), "bad_test.go", bad)
225		if err != nil {
226			t.Fatal(err)
227		}
228		want := []string{
229			"imports " + termenvPath, "composite literal tea.KeyMsg", "tea.KeyEnter",
230			"composite literal bt.Key", "bt.KeyCtrlC", ".Runes", ".Alt", ".Paste", "lipgloss.SetColorProfile",
231		}
232		for _, w := range want {
